const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-180, -90, 180, -60], null, false); // Antarctic region south of 60S

  const date1_start = '2021-01-01';
  const date1_end = '2021-01-02'; // For a single day, filter to the day after
  const date2_start = '2021-10-07';
  const date2_end = '2021-10-08';

  // Ozone hole threshold: 220 Dobson Units (DU)
  // Conversion: 1 DU = 2.687e20 molecules/m^2
  // S5P O3_column_number_density is in mol/m^2
  // 1 mol = 6.022e23 molecules (Avogadro's number)
  // So, 1 mol/m^2 = 6.022e23 molecules/m^2
  // Conversion factor from mol/m^2 to DU = (mol/m^2 * 6.022e23) / 2.687e20 = 2241.15 DU/(mol/m^2)
  const DU_TO_MOL_M2 = 1 / 2241.15; // From DU to mol/m^2
  const OZONE_HOLE_THRESHOLD_DU = 220;
  const OZONE_HOLE_THRESHOLD_MOL_M2 = OZONE_HOLE_THRESHOLD_DU * DU_TO_MOL_M2; // approx 0.09816 mol/m^2

  // 2. Data Acquisition & Check
  const s5p_ozone = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
    .select('O3_column_number_density', 'qa_value');

  // Filter for date 1 (Jan 1, 2021)
  let col1 = s5p_ozone
    .filterDate(date1_start, date1_end)
    .filterBounds(region)
    .filter(ee.Filter.gt('qa_value', 0.5)); // Quality assurance > 50%

  if (col1.size().getInfo() === 0) {
    console.log("No Sentinel-5P data for Jan 1, 2021 after QA filter.");
    console.log("C1");
    return;
  }
  const img1 = col1.mosaic();

  // Filter for date 2 (Oct 7, 2021)
  let col2 = s5p_ozone
    .filterDate(date2_start, date2_end)
    .filterBounds(region)
    .filter(ee.Filter.gt('qa_value', 0.5)); // Quality assurance > 50%

  if (col2.size().getInfo() === 0) {
    console.log("No Sentinel-5P data for Oct 7, 2021 after QA filter.");
    console.log("C1");
    return;
  }
  const img2 = col2.mosaic();

  // 3. Processing: Identify ozone hole pixels
  // Mask pixels where ozone is above the threshold
  const ozone_hole_1 = img1.lte(OZONE_HOLE_THRESHOLD_MOL_M2);
  const ozone_hole_2 = img2.lte(OZONE_HOLE_THRESHOLD_MOL_M2);

  // Calculate area (pixel count * pixel area)
  // Use a coarse scale to avoid memory issues and timeouts.
  // Sentinel-5P resolution is ~5.5km, so 5000m scale is reasonable.
  const scale = 5000; // meters

  const getOzoneHoleArea = (ozone_hole_mask, date_str) => {
    const pixel_count = ozone_hole_mask.reduceRegion({
      reducer: ee.Reducer.sum(), // Sum of 1s (ozone hole pixels)
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('O3_column_number_density'); // The band name from the masked image

    // Pixel area for the given scale
    const pixel_area_sq_m = ee.Image.pixelArea().reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('pixel_area').multiply(pixel_count); // Total area of ozone hole pixels

    return pixel_area_sq_m.getInfo();
  };

  const area1_sq_m = getOzoneHoleArea(ozone_hole_1, date1_start);
  const area2_sq_m = getOzoneHoleArea(ozone_hole_2, date2_start);

  // Convert to km^2 for readability
  const area1_sq_km = area1_sq_m / 1e6;
  const area2_sq_km = area2_sq_m / 1e6;

  // 4. Validation & Final Answer
  if (area1_sq_km === null || isNaN(area1_sq_km) || area2_sq_km === null || isNaN(area2_sq_km)) {
    console.log("C3"); // Calculation failed
    return;
  }

  // Check for C2 (No valid pixels for ozone hole after thresholding)
  if (area1_sq_km === 0) {
    console.log(`Jan 1, 2021: 0 valid ozone hole pixels.`);
  }
  if (area2_sq_km === 0) {
    console.log(`Oct 7, 2021: 0 valid ozone hole pixels.`);
  }

  console.log(`Jan 1, 2021 Ozone Hole Area (South of 60S): ${area1_sq_km.toFixed(2)} km^2`);
  console.log(`Oct 7, 2021 Ozone Hole Area (South of 60S): ${area2_sq_km.toFixed(2)} km^2`);

  if (area2_sq_km > area1_sq_km) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
